insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('spatial-intelligence', 'Spatial Intelligence', 'Rotation, orientation, shape matching and 2D/3D transformations using SVG-based visual reasoning matrices.', 'Spatial Intelligence measures non-verbal visual pattern reasoning through 3x3 matrix-completion puzzles, where shapes progress by rule across rows and columns (shape, fill, size, color, quantity, position, or compound combinations) and one cell is missing.', 'box', (select id from assessment_categories where key = 'spatial'), ('pattern_recognition')::assessment_engine_type, ('hard')::assessment_difficulty, 15, 10, false, ('free')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'spatial', 'Spatial Intelligence', 'Composite measure of non-verbal visual pattern reasoning across shape, fill, size, color, quantity, and compound transformation rules in matrix-completion puzzles.', true, 'spatial', 1)
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'overall', 0, 30, 'Developing', 'Spatial pattern reasoning is still emerging. Multi-step matrix rules involving shape, color, size, and fill changing at once were difficult to track under time pressure.', ARRAY['Practice simple shape-sequence puzzles daily for 10 minutes to build pattern-detection basics.', 'Isolate one attribute at a time (shape, then color, then size) before trying to combine rules.', 'Use physical objects or blocks to build intuition for how shapes transform in a sequence.']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'overall', 31, 50, 'Average', 'Solid, typical spatial reasoning performance. Single-rule progressions (shape order, fill, size) were handled well, but compound and diagonal rules were inconsistent.', ARRAY['Practice scanning both rows and columns simultaneously, since harder matrices combine rules across both.', 'Try mentally rotating or transforming objects before checking answers to build visualization strength.', 'Time yourself on easier puzzles first to build speed before tackling compound-rule items.']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'overall', 51, 70, 'Strong', 'Above-average spatial intelligence. Color rotation, size/fill progressions, and quantity changes were identified reliably, with only the most compound rules causing occasional errors.', ARRAY['Challenge yourself with matrices that combine three or more changing attributes at once.', 'Practice diagonal and symmetry-based logic puzzles to sharpen multi-axis reasoning.', 'Keep timing yourself to convert accuracy gains into speed gains.']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'overall', 71, 85, 'Very Strong', 'Excellent spatial pattern reasoning. Compound rules combining shape, color, fill, and position were solved quickly and accurately, placing performance well above typical adult norms.', ARRAY['Seek out advanced non-verbal reasoning batteries for continued challenge.', 'Apply this strength in fields like engineering, architecture, design, or data visualization.', 'Mentor others on rule-decomposition strategies for matrix puzzles.']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'spatial-intelligence'), 'overall', 86, 100, 'Exceptional', 'Elite spatial intelligence. Every rule type — simple progressions, rotations, diagonal logic, toggling, compound combinations, and symmetry — was solved with near-perfect accuracy, placing this result in the top tier of the population.', ARRAY['Pursue advanced spatial domains such as 3D CAD, chess, surgery, or theoretical mathematics.', 'Benchmark against timed, higher-difficulty visual reasoning batteries to keep finding ceiling.', 'Pair this strength with verbal or numerical assessments to build a complete cognitive profile.']::text[], NULL, 5);
